package com.bank.history.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDate;

@Entity
@Table(name = "transaction_records")
public class TransactionRecord {
    @Id
    // SEQUENCE (NOT IDENTITY) → ids known before insert → inserts can batch
    @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "txn_gen")
    @SequenceGenerator(name = "txn_gen", sequenceName = "txn_seq", allocationSize = 50)
    private Long id;

    private String accountId;
    private BigDecimal amount;
    private String type;
    private LocalDate txnDate;

    protected TransactionRecord() { }
    public TransactionRecord(String accountId, BigDecimal amount, String type, LocalDate d) {
        this.accountId = accountId; this.amount = amount; this.type = type; this.txnDate = d;
    }
}
