package com.bank.history.service;

import com.bank.history.model.TransactionRecord;
import jakarta.persistence.EntityManager;
import jakarta.persistence.PersistenceContext;
import lombok.extern.slf4j.Slf4j;
import org.hibernate.Session;
import org.hibernate.stat.Statistics;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;

@Service
@Slf4j
public class HistoryBackfillService {

    @PersistenceContext
    private EntityManager em;

    private static final int BATCH = 50;  // match hibernate.jdbc.batch_size

    @Transactional
    public void backfill(List<BigDecimal> amounts) {
        int i = 0;
        for (BigDecimal amt : amounts) {
            em.persist(new TransactionRecord(
                    "SAV2001", amt, "CREDIT", LocalDate.now()));
            if (++i % BATCH == 0) {
                em.flush();  // flushes a full JDBC batch of 50 INSERTs in one round trip
                em.clear();  // keep memory bounded
            }
        }
        em.flush();

        Statistics stats = em.unwrap(Session.class).getSessionFactory().getStatistics();
        log.info("Backfill done: {} rows; prepared statements={}, flushes={}",
                amounts.size(), stats.getPrepareStatementCount(), stats.getFlushCount());
    }
}
